items.sparql:
SELECT ?b ?use WHERE {
  ?b a jgk:Building ; jgk:useName ?use ; geo:hasDefaultGeometry/geo:asWKT ?w .
  FILTER(?use = "교육연구시설")
  FILTER(geof:sfIntersects(?w, {{NEAR:https://yeodh10.github.io/jeungmi-geokg/id/station/1150010200106660040000001:500}}))
} ORDER BY ?b

SELECT ?b ?f ?use WHERE {
  ?b a jgk:Building ; jgk:floorsAbove ?f .
  OPTIONAL { ?b jgk:useName ?use }
  FILTER(?f >= 20)
} ORDER BY DESC(?f) ?b

SELECT ?b ?f WHERE {
  ?b a jgk:Building ; jgk:useName "공동주택" ; jgk:floorsAbove ?f .
  FILTER(?f >= 15)
} ORDER BY DESC(?f) ?b

SELECT ?b (COUNT(DISTINCT ?e) AS ?k) WHERE {
  ?b a jgk:Building ; jgk:hasEntrance ?e .
} GROUP BY ?b HAVING (COUNT(DISTINCT ?e) >= 2) ORDER BY DESC(?k) ?b

SELECT ?b ?d ?use WHERE {
  ?b a jgk:Building ; jgk:approvalDate ?d .
  OPTIONAL { ?b jgk:useName ?use }
  FILTER(?d < "1980-01-01"^^<http://www.w3.org/2001/XMLSchema#date>)
} ORDER BY ?d ?b

SELECT DISTINCT ?b ?use WHERE {
  ?b a jgk:Building ; jgk:status jgk:AddressUnlinked ; rdfs:label ?l .
  OPTIONAL { ?b jgk:useName ?use }
} ORDER BY ?b

SELECT ?p (COUNT(DISTINCT ?x) AS ?k) WHERE {
  ?x a jgk:Building ; jgk:locatedOn ?p .
} GROUP BY ?p HAVING (COUNT(DISTINCT ?x) >= 3) ORDER BY DESC(?k) ?p

SELECT ?s WHERE {
  ?s a jgk:Sensor ; geo:hasDefaultGeometry/geo:asWKT ?w .
  FILTER(geof:sfIntersects(?w, {{NEAR:https://yeodh10.github.io/jeungmi-geokg/id/station/1150010200106660040000001:600}}))
} ORDER BY ?s

SELECT DISTINCT ?b ?use WHERE {
  ?b a jgk:Building ; jgk:status jgk:AddressUnlinked ; jgk:inLegalDong ?d .
  ?d rdfs:label "등촌동"@ko .
  OPTIONAL { ?b jgk:useName ?use }
} ORDER BY ?b

SELECT DISTINCT ?b ?use WHERE {
  ?b a jgk:Building ; jgk:status jgk:AddressUnlinked ; jgk:inLegalDong ?d .
  ?d rdfs:label "염창동"@ko .
  OPTIONAL { ?b jgk:useName ?use }
} ORDER BY ?b

SELECT DISTINCT ?b ?f WHERE {
  ?b a jgk:Building ; jgk:useName "공동주택" ; jgk:inLegalDong ?d .
  ?d rdfs:label "가양동"@ko .
  OPTIONAL { ?b jgk:floorsAbove ?f }
} ORDER BY ?b

SELECT ?e ?t ?b WHERE {
  ?e a jgk:BuildingEntrance ; jgk:entranceType ?t .
  ?b jgk:hasEntrance ?e .
  FILTER(?t != "주출입구")
} ORDER BY ?t ?e ?b

SELECT DISTINCT ?b ?f WHERE {
  ?b a jgk:Building ; rdfs:label ?l .
  OPTIONAL { ?b jgk:floorsAbove ?f }
  FILTER(CONTAINS(STR(?l), "아파트"))
} ORDER BY ?b

SELECT DISTINCT ?b ?use WHERE {
  ?b a jgk:Building ; jgk:addressRoad ?r .
  ?r rdfs:label "양천로"@ko .
  OPTIONAL { ?b jgk:useName ?use }
} ORDER BY ?b

SELECT ?s ?b WHERE {
  ?s a jgk:Business ; jgk:categorySmall "카페" ; jgk:inBuilding ?b ; geo:hasDefaultGeometry/geo:asWKT ?w .
  FILTER(geof:sfIntersects(?w, {{NEAR:https://yeodh10.github.io/jeungmi-geokg/id/station/1150010200106660040000001:300}}))
} ORDER BY ?b ?s

SELECT ?p ?h ?b WHERE {
  ?p a jgk:Parcel ; jgk:households ?h .
  ?b a jgk:Building ; jgk:locatedOn ?p .
  FILTER(?h >= 1000)
} ORDER BY DESC(?h) ?p ?b
